package api

import "trstctl.com/trstctl/internal/authz"

// caHierarchyRoutes is the served private-CA hierarchy: key ceremonies, the
// authorities they create, import, rotate, re-key, revoke and cross-sign, and
// their public receipts.
//
// Split out of api.go for the served-surface file budget, like
// routes_platform.go: the route table is the bulk of api.go, and a coherent
// workflow moved out is the split the budget asks for rather than a waiver.
func (a *API) caHierarchyRoutes(idPath []param) []route {
	caCeremonyPath := []param{pathUUID("id")}
	caAuthorityPath := []param{pathUUID("id")}
	return []route{
		{method: "POST", path: "/api/v1/ca/ceremonies/preview", opID: "previewCACeremony", summary: "Validate and explain an exact CA key ceremony without writing state, creating keys, or contacting an authority", handler: a.previewCACeremony, reqSchema: "CACeremonyStartRequest", resSchema: "CACeremonyPlanPreview", successCode: "200", perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/ceremonies", opID: "createCACeremony", summary: "Start an m-of-n CA key ceremony", handler: a.createCACeremony, reqSchema: "CACeremonyStartRequest", resSchema: "CAKeyCeremony", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "GET", path: "/api/v1/ca/ceremonies/{id}", opID: "getCACeremony", summary: "Get a CA key ceremony", handler: a.getCACeremony, pathParams: caCeremonyPath, resSchema: "CAKeyCeremony", successCode: "200", perm: authz.IssuersRead},
		{method: "POST", path: "/api/v1/ca/ceremonies/{id}/approvals", opID: "approveCACeremony", summary: "Approve a CA key ceremony", handler: a.approveCACeremony, pathParams: caCeremonyPath, resSchema: "CAKeyCeremony", successCode: "200", mutation: true, approval: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/ceremonies/{id}/cancel", opID: "cancelCACeremony", summary: "Cancel a pending CA key ceremony with an audit reason", handler: a.cancelCACeremony, pathParams: caCeremonyPath, reqSchema: "CACeremonyCancelRequest", resSchema: "CAKeyCeremony", successCode: "200", mutation: true, perm: authz.IssuersWrite},
		{method: "GET", path: "/api/v1/ca/discovery", opID: "listCADiscoveryInventory", summary: "List public and private CA discovery inventory", handler: a.listCADiscoveryInventory, resSchema: "CADiscoveryInventory", successCode: "200", perm: authz.IssuersRead},
		{method: "GET", path: "/api/v1/ca/authorities", opID: "listCAAuthorities", summary: "List served CA authorities", handler: a.listCAAuthorities, resSchema: "CAAuthorityList", successCode: "200", perm: authz.IssuersRead},
		{method: "POST", path: "/api/v1/ca/authorities/roots", opID: "createRootCA", summary: "Create a signer-backed root CA after ceremony quorum", handler: a.createRootCA, reqSchema: "CACreateRootRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/offline-roots", opID: "importOfflineRootCA", summary: "Import an offline root CA certificate after ceremony quorum", handler: a.importOfflineRootCA, reqSchema: "CAImportOfflineRootRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/imported", opID: "importExistingCA", summary: "Import an existing signer-backed CA certificate chain after ceremony quorum", handler: a.importExistingCA, reqSchema: "CAImportExistingRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/imported/csr", opID: "prepareExistingImportCSR", summary: "Reserve a tenant-bound CA signing key and durable public CSR for an external issuer", handler: a.prepareExistingImportCSR, reqSchema: "CAPrepareExistingImportCSRRequest", resSchema: "CAExistingImportCSR", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/imported/key-offer", opID: "prepareCAKeyImport", summary: "Offer the signer's one-time import key for an approved import_ca_key ceremony", handler: a.prepareCAKeyImport, reqSchema: "CAKeyImportOfferRequest", resSchema: "CAKeyImportOffer", successCode: "200", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/imported/key", opID: "importCAKey", summary: "Take a sealed CA private key into signer custody and bind its approved chain", handler: a.importCAKey, reqSchema: "CAImportKeyRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "GET", path: "/api/v1/ca/authorities/imported/csr/{ceremony_id}", opID: "getExistingImportCSR", summary: "Read a completed public CSR preparation by ceremony", handler: a.getExistingImportCSR, pathParams: []param{pathUUID("ceremony_id")}, resSchema: "CAExistingImportCSR", successCode: "200", perm: authz.IssuersRead},
		{method: "POST", path: "/api/v1/ca/authorities/intermediates", opID: "createIntermediateCA", summary: "Create a signer-backed intermediate CA after ceremony quorum", handler: a.createIntermediateCA, reqSchema: "CACreateIntermediateRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/offline-intermediates/csr", opID: "createOfflineIntermediateCSR", summary: "Create a signer-backed intermediate CSR for an offline root", handler: a.createOfflineIntermediateCSR, pathParams: caAuthorityPath, reqSchema: "CACreateOfflineIntermediateCSRRequest", resSchema: "CAIntermediateCSR", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/offline-intermediates", opID: "importOfflineIntermediateCA", summary: "Import an offline-root-signed intermediate CA certificate", handler: a.importOfflineIntermediateCA, pathParams: caAuthorityPath, reqSchema: "CAImportOfflineIntermediateRequest", resSchema: "CAAuthority", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/intermediates/csr", opID: "issueIntermediateCAFromCSR", summary: "Sign an external intermediate CA CSR from a served CA authority after ceremony quorum", handler: a.issueHierarchyIntermediateCSR, pathParams: caAuthorityPath, reqSchema: "CAIssueIntermediateRequest", resSchema: "CAIssuedIntermediate", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/issue", opID: "issueHierarchyLeaf", summary: "Issue a leaf certificate from a served CA authority", handler: a.issueHierarchyLeaf, pathParams: caAuthorityPath, reqSchema: "CAIssueLeafRequest", resSchema: "CAIssuedLeaf", successCode: "201", mutation: true, perm: authz.CertsIssue, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/rotate/preview", opID: "previewCAAuthorityRotation", summary: "Validate and explain a CA rotation without changing authority state", handler: a.previewCAAuthorityRotation, pathParams: caAuthorityPath, reqSchema: "CAAuthorityRotationRequest", resSchema: "CAAuthorityRotationPlanPreview", successCode: "200", perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/rotate", opID: "rotateCAAuthority", summary: "Activate a signer-backed successor CA without changing the stable issue URL", handler: a.rotateCAAuthority, pathParams: caAuthorityPath, reqSchema: "CAAuthorityRotationRequest", resSchema: "CAAuthorityRotation", successCode: "200", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/rekey", opID: "rekeyCAAuthority", summary: "Re-key a signer-backed CA authority after ceremony quorum", handler: a.rekeyCAAuthority, pathParams: caAuthorityPath, reqSchema: "CAAuthorityRekeyRequest", resSchema: "CAAuthorityRotation", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/revoke", opID: "revokeCAAuthority", summary: "Revoke a signer-backed CA authority's key after ceremony quorum", handler: a.revokeCAAuthority, pathParams: caAuthorityPath, reqSchema: "CAAuthorityRevokeRequest", resSchema: "CAAuthorityRevocation", successCode: "200", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/cross-sign", opID: "crossSignCAAuthority", summary: "Cross-sign a CA certificate with a signer-backed authority after ceremony quorum", handler: a.crossSignCAAuthority, pathParams: caAuthorityPath, reqSchema: "CACrossSignRequest", resSchema: "CACrossSign", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "GET", path: "/api/v1/ca/cross-signs/{id}", opID: "getCACrossSignReceipt", summary: "Read the event-projected public cross-certificate by ceremony ID", handler: a.getCACrossSignReceipt, pathParams: idPath, resSchema: "CACrossSign", successCode: "200", perm: authz.IssuersRead},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/offline-cross-signs", opID: "importOfflineRootCrossSign", summary: "Verify and import a public cross-certificate produced by an offline root", handler: a.importOfflineRootCrossSign, pathParams: caAuthorityPath, reqSchema: "CAOfflineCrossSignImportRequest", resSchema: "CACrossSign", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "POST", path: "/api/v1/ca/authorities/{id}/offline-rekey", opID: "rekeyOfflineRoot", summary: "Import and activate an offline-root successor with bidirectional cross-signatures", handler: a.rekeyOfflineRoot, pathParams: caAuthorityPath, reqSchema: "CAOfflineRootRekeyRequest", resSchema: "CAOfflineRootRekey", successCode: "201", mutation: true, perm: authz.IssuersWrite, scope: scopeIssuerPath("id")},
		{method: "GET", path: "/api/v1/ca/offline-rekeys/{id}", opID: "getOfflineRootRekeyReceipt", summary: "Recover an offline-root successor and both public trust paths by ceremony ID", handler: a.getOfflineRootRekeyReceipt, pathParams: idPath, resSchema: "CAOfflineRootRekey", successCode: "200", perm: authz.IssuersRead},
	}
}
